glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
  in vec2 a_uv0;
  out vec2 v_uv0;
#endif
void main() {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
    pos = cc_matViewProj * cc_matWorld * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
    v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
#if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
#endif
uniform colorReplacement {
  vec4 originalColor;
  vec4 targetColor;
};
void main() {
  vec4 texColor = vec4(1.0);
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    texColor.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    texColor.a *= texture_tmp.a;
  #else
    texColor *= texture_tmp;
  #endif
  vec4 finalColor;
  #if USE_TINT
    finalColor.a = v_color.a * texColor.a;
    finalColor.rgb = ((texColor.a - 1.0) * v_dark.a + 1.0 - texColor.rgb) * v_dark.rgb + texColor.rgb * v_color.rgb;
  #else
    finalColor = texColor * v_color;
  #endif
  #if USE_COLOR_REPLACEMENT
    vec3 pixelRgb = finalColor.rgb;
    vec3 originalRgb = originalColor.rgb;
    vec3 targetRgb = targetColor.rgb;
    float colorDistance = distance(pixelRgb, originalRgb);
    float blendFactor = smoothstep(0.1, 0.3, colorDistance);
    finalColor.rgb = mix(targetRgb, pixelRgb, blendFactor);
  #endif
  ALPHA_TEST(finalColor);
  gl_FragColor = finalColor;
}

